// Regenerate the auto-generated migration table in
// docs/SUPABASE_MIGRATIONS.md from supabase/migrations/ + the readiness
// manifest instead of hand-maintaining a table and a count. `--check` fails
// closed on drift so stale docs cannot merge silently.
import { createHash } from 'node:crypto'
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..')

const MIGRATION_FILE_PATTERN = /^(\d{12,14})_.+\.sql$/
export const BEGIN_MARKER = '<!-- AUTO-GENERATED:MIGRATIONS:BEGIN -->'
export const END_MARKER = '<!-- AUTO-GENERATED:MIGRATIONS:END -->'

function migrationsDirectory(root) {
  return resolve(root, 'supabase/migrations')
}

function manifestFilePath(root) {
  return resolve(root, 'scripts/sql/verify/manifest.json')
}

function descriptionsFilePath(root) {
  return resolve(root, 'scripts/migration-doc-descriptions.json')
}

export function docFilePath(root) {
  return resolve(root, 'docs/SUPABASE_MIGRATIONS.md')
}

export function readMigrationFilenames(root) {
  return readdirSync(migrationsDirectory(root))
    .filter((name) => MIGRATION_FILE_PATTERN.test(name))
    .sort()
}

export function readManifestRaw(root) {
  return readFileSync(manifestFilePath(root), 'utf8')
}

export function readManifest(root) {
  return JSON.parse(readManifestRaw(root))
}

export function readDescriptions(root) {
  return JSON.parse(readFileSync(descriptionsFilePath(root), 'utf8'))
}

function normalizeLineEndings(text) {
  return text.replace(/\r\n?/g, '\n')
}

export function manifestHash(root) {
  // Git may materialize text files with CRLF on Windows even though the
  // canonical repository form is LF. Hash the semantic text representation so
  // generated documentation is stable across checkout platforms.
  const normalizedManifest = normalizeLineEndings(readManifestRaw(root))
  return createHash('sha256').update(normalizedManifest).digest('hex')
}

function assertNoDuplicates(versions, label) {
  const seen = new Set()
  for (const version of versions) {
    if (seen.has(version)) {
      throw new Error(`SQA_MIGRATION_DOC_DUPLICATE_VERSION: ${version} (${label})`)
    }
    seen.add(version)
  }
}

/**
 * Builds the ordered, described migration list, failing closed on any
 * drift between supabase/migrations/, the readiness manifest, and the
 * description sidecar.
 */
export function buildMigrationEntries(root = repositoryRoot) {
  const filenames = readMigrationFilenames(root)
  const versions = filenames.map((name) => MIGRATION_FILE_PATTERN.exec(name)[1])
  assertNoDuplicates(versions, 'supabase/migrations')

  const manifest = readManifest(root)
  const manifestVersions = manifest.migrationVersions
  if (!Array.isArray(manifestVersions)) {
    throw new Error('SQA_MIGRATION_DOC_MANIFEST_SCHEMA: manifest.migrationVersions must be an array')
  }
  assertNoDuplicates(manifestVersions, 'manifest.json')

  const missingFromManifest = versions.filter((version) => !manifestVersions.includes(version))
  if (missingFromManifest.length > 0) {
    throw new Error(`SQA_MIGRATION_DOC_MISSING_FROM_MANIFEST: ${missingFromManifest.join(', ')}`)
  }
  const missingMigrationFiles = manifestVersions.filter((version) => !versions.includes(version))
  if (missingMigrationFiles.length > 0) {
    throw new Error(`SQA_MIGRATION_DOC_MISSING_MIGRATION: ${missingMigrationFiles.join(', ')}`)
  }
  if (
    manifestVersions.length !== versions.length
    || manifestVersions.some((version, index) => version !== versions[index])
  ) {
    throw new Error(
      'SQA_MIGRATION_DOC_BAD_ORDER: manifest.json migrationVersions must match the chronological '
      + 'order of files on disk',
    )
  }

  const descriptions = readDescriptions(root)
  const missingDescriptions = filenames.filter(
    (name) => typeof descriptions[name] !== 'string' || descriptions[name].trim() === '',
  )
  if (missingDescriptions.length > 0) {
    throw new Error(`SQA_MIGRATION_DOC_MISSING_DESCRIPTION: ${missingDescriptions.join(', ')}`)
  }

  return filenames.map((filename, index) => ({
    filename,
    version: versions[index],
    description: descriptions[filename],
  }))
}

function renderTable(entries) {
  const rows = entries.map((entry) => `| \`${entry.filename}\` | ${entry.description} |`)
  return ['| 파일 | 내용 |', '|------|------|', ...rows].join('\n')
}

/** Deterministic — no timestamps, only content already committed to the repo. */
export function renderGeneratedBlock(root = repositoryRoot) {
  const entries = buildMigrationEntries(root)
  const latest = entries[entries.length - 1]
  const hash = manifestHash(root)
  return [
    BEGIN_MARKER,
    '<!-- Generated by `node scripts/generate-migration-doc.mjs`. Do not hand-edit inside this',
    '     block — run `npm run docs:migrations` to regenerate it. -->',
    '',
    `- **최신 migration**: \`${latest.filename}\` (version \`${latest.version}\`)`,
    `- **Migration 개수**: ${entries.length}`,
    `- **manifest.json SHA-256**: \`${hash}\``,
    '',
    renderTable(entries),
    '',
    END_MARKER,
  ].join('\n')
}

export function injectGeneratedBlock(documentText, block) {
  const beginIndex = documentText.indexOf(BEGIN_MARKER)
  const endIndex = documentText.indexOf(END_MARKER)
  if (beginIndex === -1 || endIndex === -1) {
    throw new Error(
      'SQA_MIGRATION_DOC_MARKERS_MISSING: docs/SUPABASE_MIGRATIONS.md must contain '
      + `${BEGIN_MARKER} and ${END_MARKER} markers`,
    )
  }
  if (endIndex < beginIndex) {
    throw new Error('SQA_MIGRATION_DOC_MARKERS_ORDER: END marker appears before BEGIN marker')
  }
  const before = documentText.slice(0, beginIndex)
  const after = documentText.slice(endIndex + END_MARKER.length)
  return `${before}${block}${after}`
}

export function generateMigrationDoc(root = repositoryRoot) {
  const block = renderGeneratedBlock(root)
  // Compare canonical text rather than checkout-specific bytes. Otherwise a
  // CRLF working tree reports drift even when the generated content is current.
  const currentText = normalizeLineEndings(readFileSync(docFilePath(root), 'utf8'))
  const nextText = injectGeneratedBlock(currentText, block)
  return { currentText, nextText, changed: currentText !== nextText }
}

function runCli() {
  const checkMode = process.argv.includes('--check')
  try {
    const { nextText, changed } = generateMigrationDoc(repositoryRoot)
    if (changed) {
      if (checkMode) {
        console.error(
          'SQA_MIGRATION_DOC_DRIFT: docs/SUPABASE_MIGRATIONS.md is out of date with '
          + 'supabase/migrations/ and scripts/sql/verify/manifest.json. Run `npm run docs:migrations`.',
        )
        process.exitCode = 1
        return
      }
      writeFileSync(docFilePath(repositoryRoot), nextText, 'utf8')
      console.log('Migration docs regenerated: docs/SUPABASE_MIGRATIONS.md')
      return
    }
    console.log('Migration docs OK: docs/SUPABASE_MIGRATIONS.md matches manifest (no drift).')
  } catch (error) {
    console.error(error instanceof Error ? error.message : String(error))
    process.exitCode = 1
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runCli()
}
